// Example: a method that fetches data
fetchData() {
  this.loading = true;
  this.dataService.getData().subscribe({
    next: (response) => {
      this.data = response;
      this.loading = false;
    },
    error: (error) => {
      console.error('Error fetching data:', error);
      this.loading = false;
    }
  });
}

